 t=time.monotonic();assert not(ROOT/'runtime/STOP').exists();out=ROOT/'validation/integrated'/sys.argv[1];out.mkdir(exist_ok=False);shutil.copyfile(__file__,out/'verifier.py');src=ROOT/'validation/integrated'/sys.argv[2]/'summary.json';s=json.loads(src.read_text());checks=dict(no_physical_regularization=s['physical_regularization']==0,no_physical_update=s['actual_support_updates']==0,no_rejected_state_acceptance=s['accepted_linear_steps']==0,source_field_hash=sha(REPO/s['source_field']['path'])==s['source_field']['SHA256']);metrics={}
